/**
 * alice appearance for the DeepSeek Harness Work Pet (`dsh-workpet`).
 * 由 Mori 2D 雪碧（半身 4×4 图集）裁出的单帧素材驱动，100 × 80 SVG 盒子。
 */
window.__ModuleLoader__.load({
  id: 'dsh-workpet-alice',
  factory: (require) => {
    const React = require('react')

    // =====================================================================
    // 1. ARTWORK — one frame per state, cut from the Mori sprite sheets.
    // =====================================================================
    const ART = {
      idle: 'data:image/webp;base64,',
      sleeping: 'data:image/webp;base64,',
      recording: 'data:image/webp;base64,',
      thinking: 'data:image/webp;base64,',
      done: 'data:image/webp;base64,',
      error: 'data:image/webp;base64,',
      walking: 'data:image/webp;base64,',
      dragging: 'data:image/webp;base64,',
    }
    const RATIO = {"idle": 1.021, "sleeping": 1.042, "recording": 1.046, "thinking": 1.064, "done": 1.042, "error": 1.046, "walking": 1.034, "dragging": 1.046}

    const ACT = {
      "absent": [
            "sleeping",
            "al-breathe-slow"
      ],
      "idle": [
            "idle",
            "al-breathe"
      ],
      "sleeping": [
            "sleeping",
            "al-breathe-slow"
      ],
      "thinking": [
            "thinking",
            "al-tilt"
      ],
      "writing": [
            "recording",
            "al-bob"
      ],
      "tool": [
            "walking",
            "al-sway"
      ],
      "retrying": [
            "error",
            "al-shake"
      ],
      "awaiting": [
            "recording",
            "al-bob"
      ],
      "delegating": [
            "idle",
            "al-look"
      ],
      "done": [
            "done",
            "al-hop"
      ],
      "error": [
            "error",
            "al-shake"
      ],
      "petted": [
            "done",
            "al-pet"
      ],
      "dragged": [
            "dragging",
            "al-dangle"
      ]
}

    function figure(scene) {
      const [state, cls] = ACT[scene.activity] || ACT.idle
      const uri = ART[state]
      const h = 74
      const w = Math.min(96, h * (RATIO[state] || 1))
      const x = (100 - w) / 2
      const y = 78 - h
      return `
        <ellipse cx="50" cy="76.5" rx="${(w / 2) * 0.72}" ry="3.2" fill="#000" opacity="0.16"/>
        <g class="${cls}" style="transform-origin:${x + w / 2}px 78px">
          <image href="${uri}" x="${x.toFixed(1)}" y="${y}" width="${w.toFixed(1)}" height="${h}"
                 preserveAspectRatio="xMidYMax meet"/>
        </g>`
    }

    function AliceFigure({ scene, compact }) {
      const markup = figure(scene)
      return React.createElement('svg', {
        className: 'al',
        viewBox: '0 0 100 80',
        width: '100%',
        height: '100%',
        'aria-hidden': true,
        dangerouslySetInnerHTML: { __html: markup },
      })
    }

    // =====================================================================
    // 2. ANIMATION
    // =====================================================================
    const CSS = `
.al{overflow:visible;}
.al-breathe,.al-breathe-slow,.al-bob,.al-tilt,.al-sway,.al-shake,.al-hop,.al-look,.al-pet,.al-dangle{
  transform-box:view-box;
}
.al-breathe{animation:al-breathe 3s ease-in-out infinite;}
.al-breathe-slow{animation:al-breathe 5s ease-in-out infinite;}
.al-bob{animation:al-bob 1.2s ease-in-out infinite;}
.al-tilt{animation:al-tilt 2.4s ease-in-out infinite;}
.al-sway{animation:al-sway 1.5s ease-in-out infinite;}
.al-shake{animation:al-shake .5s ease-in-out infinite;}
.al-hop{animation:al-hop 1.1s ease-in-out infinite;}
.al-look{animation:al-look 3.4s ease-in-out infinite;}
.al-pet{animation:al-pet 1.6s ease-in-out infinite;}
.al-dangle{animation:al-dangle 1.2s ease-in-out infinite;}
@keyframes al-breathe{0%,100%{transform:translateY(0) scaleY(1);}50%{transform:translateY(-0.8px) scaleY(1.012);}}
@keyframes al-bob{0%,100%{transform:translateY(0);}50%{transform:translateY(-1.6px);}}
@keyframes al-tilt{0%,100%{transform:rotate(-2deg);}50%{transform:rotate(2deg);}}
@keyframes al-sway{0%,100%{transform:rotate(-3.5deg);}50%{transform:rotate(3.5deg);}}
@keyframes al-shake{0%,100%{transform:translateX(-1.2px);}50%{transform:translateX(1.2px);}}
@keyframes al-hop{0%,100%{transform:translateY(0);}35%{transform:translateY(-4px);}70%{transform:translateY(0);}}
@keyframes al-look{0%,100%{transform:rotate(0deg);}45%{transform:rotate(-1.5deg);}75%{transform:rotate(1.5deg);}}
@keyframes al-pet{0%,100%{transform:translateY(0) scale(1);}50%{transform:translateY(-1px) scale(1.03);}}
@keyframes al-dangle{0%,100%{transform:rotate(-6deg);}50%{transform:rotate(6deg);}}
@media (prefers-reduced-motion:reduce){.al *{animation:none !important;}}
`

    // =====================================================================
    // 3. PLUG-IN
    // =====================================================================
    const dictionaries = {
      zh: { title: 'alice', description: '戴圆框眼镜、深棕短卷发、棕色西装的半身少女（Mori 雪碧转制）。' },
      en: { title: 'alice', description: 'A bob-haired woman with round glasses in a brown blazer, converted from the Mori sprite pack.' },
    }

    function insertStyles() {
      if (typeof document === 'undefined') return () => {}
      const tag = document.createElement('style')
      tag.dataset.plugin = 'dsh-workpet-alice'
      tag.textContent = CSS
      document.head.appendChild(tag)
      return () => tag.remove()
    }

    return {
      inject: ['workpet', 'locale'],
      apply(ctx) {
        ctx.effect(insertStyles, 'workpet-alice: stylesheet')
        ctx.effect(() => ctx.locale.register('workpetAlice', dictionaries), 'workpet-alice: dictionaries')
        const t = ctx.locale.bind('workpetAlice')
        ctx.effect(() => ctx.workpet.register({
          id: 'alice',
          order: 10,
          title: () => t('title'),
          description: () => t('description'),
          Figure: AliceFigure,
        }), 'workpet-alice: skin')
      },
    }
  },
})
